-- 04-execution.sql
--
-- EXTRACTED VERBATIM from artifacts/v1/gaos-arcadedb-model.html, which is the
-- source of truth for this schema. Do not edit this file to change the model:
-- change the document, then re-extract. A deviation that lives only here is a
-- schema nobody reviewing the model document would ever see.
--
-- Applied in filename order by deploy/schema/apply.sh. Every statement carries
-- IF NOT EXISTS, so applying twice is a no-op rather than an error.

CREATE VERTEX TYPE Workflow IF NOT EXISTS EXTENDS GaosVertex;
CREATE PROPERTY Workflow.title      STRING (mandatory true, notnull true);
CREATE PROPERTY Workflow.goal       STRING (mandatory true, notnull true, min 10);
CREATE PROPERTY Workflow.status     STRING (mandatory true, notnull true, default 'DRAFT',
                 regexp 'DRAFT|PLANNED|RUNNING|BLOCKED|COMPLETED|FAILED|CANCELED');
CREATE PROPERTY Workflow.priority   STRING (default 'medium', regexp 'low|medium|high|urgent');
CREATE PROPERTY Workflow.gatePolicy STRING (default 'on_risk',
                 regexp 'always|on_risk|never');
CREATE PROPERTY Workflow.budgetUsd  FLOAT (min 0);
CREATE PROPERTY Workflow.spentUsd   FLOAT (default 0.0, min 0);

-- Task carries the scheduling decision; TaskRun carries what happened.
-- retryCount and escalationCount live here because the guards in
-- architecture §06 are per task, across all of its attempts.
CREATE VERTEX TYPE Task IF NOT EXISTS EXTENDS GaosVertex BUCKETS 8;
CREATE PROPERTY Task.title            STRING  (mandatory true, notnull true);
CREATE PROPERTY Task.status           STRING  (mandatory true, notnull true, default 'PENDING',
                 regexp 'PENDING|READY|DISPATCHED|RUNNING|REVIEW|BLOCKED|DONE|FAILED|CANCELED');
CREATE PROPERTY Task.role             STRING  (mandatory true, notnull true,
                 regexp 'planner|architect|backend|frontend|qa|security|devops');
CREATE PROPERTY Task.riskClass        STRING  (default 'normal',
                 regexp 'low|normal|high|critical');
CREATE PROPERTY Task.modelHint        STRING;
CREATE PROPERTY Task.priority         INTEGER (default 50, min 0, max 100);
CREATE PROPERTY Task.retryCount       INTEGER (default 0, min 0, max 10);
CREATE PROPERTY Task.escalationCount  INTEGER (default 0, min 0, max 5);
CREATE PROPERTY Task.approvalRequired BOOLEAN (default false);
CREATE PROPERTY Task.score            INTEGER (min 0, max 100);
CREATE PROPERTY Task.blockReason      STRING;
CREATE PROPERTY Task.leaseUntil       DATETIME;
CREATE PROPERTY Task.lastHeartbeatAt  DATETIME;

-- One row per attempt. failureSignature is the normalised error hash that
-- drives the "signature changed?" branch of the retry loop.
CREATE VERTEX TYPE TaskRun IF NOT EXISTS EXTENDS GaosVertex BUCKETS 8;
CREATE PROPERTY TaskRun.attempt          INTEGER (mandatory true, notnull true, min 1);
CREATE PROPERTY TaskRun.status           STRING  (mandatory true, notnull true,
                 regexp 'STARTED|RUNNING|EXITED|TIMEOUT|ORPHANED|KILLED');
CREATE PROPERTY TaskRun.model            STRING  (notnull true);
CREATE PROPERTY TaskRun.pid              INTEGER;
CREATE PROPERTY TaskRun.startedAt        DATETIME (mandatory true);
CREATE PROPERTY TaskRun.endedAt          DATETIME;
CREATE PROPERTY TaskRun.exitCode         INTEGER;
CREATE PROPERTY TaskRun.tokensIn         LONG  (min 0);
CREATE PROPERTY TaskRun.tokensOut        LONG  (min 0);
CREATE PROPERTY TaskRun.costUsd          FLOAT (min 0);
CREATE PROPERTY TaskRun.failureSignature STRING;
CREATE PROPERTY TaskRun.logRef           STRING;   -- object storage key

CREATE VERTEX TYPE Prompt IF NOT EXISTS EXTENDS GaosVertex;
CREATE PROPERTY Prompt.name     STRING  (mandatory true, notnull true);
CREATE PROPERTY Prompt.version  INTEGER (mandatory true, notnull true, min 1);
CREATE PROPERTY Prompt.hash     STRING  (mandatory true, notnull true);
CREATE PROPERTY Prompt.scope    STRING;
CREATE PROPERTY Prompt.template STRING;

-- The frozen slice. digest lets you prove two runs saw the same context
-- without re-reading every edge.
CREATE VERTEX TYPE ContextSlice IF NOT EXISTS EXTENDS GaosVertex;
CREATE PROPERTY ContextSlice.assembledAt DATETIME (mandatory true);
CREATE PROPERTY ContextSlice.tokenCount  INTEGER (min 0);
CREATE PROPERTY ContextSlice.nodeCount   INTEGER (min 0);
CREATE PROPERTY ContextSlice.digest      STRING;
CREATE PROPERTY ContextSlice.rendered    STRING;   -- see EXTERNAL note in §13

CREATE VERTEX TYPE Workspace IF NOT EXISTS EXTENDS GaosVertex;
CREATE PROPERTY Workspace.path       STRING (mandatory true, notnull true);
CREATE PROPERTY Workspace.branch     STRING (notnull true);
CREATE PROPERTY Workspace.state      STRING (mandatory true, notnull true, default 'ALLOCATED',
                 regexp 'ALLOCATED|PREPARED|ACTIVE|SNAPSHOTTED|RELEASED');
CREATE PROPERTY Workspace.leaseUntil DATETIME;
CREATE PROPERTY Workspace.leasedBy   STRING;
